Code Meaning Value for RAG/LLM <code>SIG_MATCH</code> Exact signature match (blacklist) Immediate block priority <code>STAT_ANOMALY</code> Statistical deviation (Z-score high) Unusual behavior, not necessarily malicious <code>PCA_OUTLIER</code> Vector outside normal cloud (latent space) Critical for 0-day detection 🎯 <code>PROT_VIOLATION</code> Protocol malformation (impossible TCP flags) Low-level technical attack <code>ENGINE_CONFLICT</code> Sniffer vs ML disagree significantly High-priority alert for LLM analysis 🚨 <p>Implementation:</p> <pre><code>// reason_codes.hpp
namespace ml_defender {

enum class ReasonCode {
    SIG_MATCH,         // Signature match
    STAT_ANOMALY,      // Statistical anomaly
    PCA_OUTLIER,       // Outside normal latent space
    PROT_VIOLATION,    // Protocol violation
    ENGINE_CONFLICT,   // Engines disagree
    UNKNOWN
};

const char* to_string(ReasonCode code) {
    switch(code) {
        case ReasonCode::SIG_MATCH:       return "SIG_MATCH";
        case ReasonCode::STAT_ANOMALY:    return "STAT_ANOMALY";
        case ReasonCode::PCA_OUTLIER:     return "PCA_OUTLIER";
        case ReasonCode::PROT_VIOLATION:  return "PROT_VIOLATION";
        case ReasonCode::ENGINE_CONFLICT: return "ENGINE_CONFLICT";
        default:                          return "UNKNOWN";
    }
}

} // namespace ml_defender
</code></pre>

